texts.docs/research/templates/roadmap/cycle-be:
layout:
  type: cycles
  cycle:
    length_weeks: 6                   # tenant-configurable
    cooldown_weeks: 2
    current: {dates_allowed: true}    # the cycle is the Now horizon
  columns:
    - {key: current, label: This cycle, maps_to: now}
    - {key: candidates, label: Next betting table, maps_to: next}
    - {key: ideas, label: Raw ideas, maps_to: later}
  swimlanes:
    group_by: team                    # applies to the current column
  hill_chart:
    show: true                        # uphill = unknowns remain, downhill = execution
    applies_to: current
  item_fields:
    title: {required: true}
    problem: {required: true}
    goal: {required: true, multiple: true, flag_if_missing: "serves no confirmed goal"}
    appetite: {enum: [small_batch, big_batch]}
    hill_position: {range: [0, 100], only_in: [current]}
    rabbit_holes: {list: true}
    no_gos: {list: true}
    team: {only_in: [current]}
    pitch_link: {required: false}
  rules:
    circuit_breaker: true             # unfinished bets return to the table; no automatic extension
  markers:
    confidence: hill_position
    appetite: tag
  variants:
    board: {not_recommended: true, fallback_template: outcome-roadmap}
    team: {hide: []}
    engineering: {show: [tracker_links]}
    public: {not_supported: true, fallback_template: now-next-later}

texts.docs/research/templates/roadmap/outcome-:
layout:
  type: matrix
  rows:
    source: confirmed_goals           # Ground Truth goals, status confirmed
    order_by: weight                  # goal weight, highest first
    header_fields: [code, title, metric, current, target, horizon, owner]
    extra_rows:
      - key: no_goal
        label: Serves no confirmed goal
        style: flagged                # always last; hidden in board and public variants
  columns:
    - {key: now, label: Now, horizon: short, dates_allowed: true}
    - {key: next, label: Next, horizon: medium, dates_allowed: false}
    - {key: later, label: Later, horizon: long, dates_allowed: false}
  column_mode: horizons               # horizons | quarters
  item_placement: per_supported_goal  # an item appears under every goal it supports
  item_fields:
    title: {required: true}
    outcome: {required: true}         # expected change in the goal metric
    goal: {required: true, multiple: true}
    contribution: {range: [0, 3]}     # from the supports edge
    confidence: {enum: [high, medium, low]}
    evidence_count: {derived: true}
    owner: {required: false}
    depends_on: {list: true}
    milestones: {list: true, only_in: [now], fields: [name, date, source]}
  markers:
    confidence: dots
    contribution: pips
    dependency: badge
    no_goal: flag
  appendix:
    opportunity_tree: {optional: true, levels: [outcome, opportunity, solution, test]}
  variants:
    board: {hide: [owner, depends_on, milestones, evidence_count], max_items_per_cell: 3, show_goal_progress: true}
    team: {hide: []}
    engineering: {show: [effort, tracker_links, drift]}
    public: {not_supported: true, fallback_template: now-next-later}

texts.docs/research/templates/roadmap/quarterl:
layout:
  type: timeline
  axis:
    unit: quarter                     # quarter | month
    span_quarters: 4                  # current + next 3; tenant can set 2-6
    today_line: true
    fiscal_year_start_month: 1
  swimlanes:
    group_by: team                    # team | theme | goal | product
  bars:
    now: {style: solid, dates: exact, label_dates: true}      # from eng-tracker estimates
    next: {style: hatched, dates: quarter_range, label_dates: false}
    later: {style: outline, dates: quarter_range, label_dates: false}
  milestones:
    glyph: diamond
    only_in: [now]
    kinds: [estimate, external, announced]
  dependencies:
    draw: arrows
    conflict_rule: blocker_ends_after_dependent_starts   # draw in warning colour
  capacity:
    strip_per_lane: true
    source: eng_tracker
    hide_if_no_estimates: true
  item_fields:
    title: {required: true}
    goal: {required: true, multiple: true, flag_if_missing: "serves no confirmed goal"}
    horizon: {enum: [now, next, later], required: true}
    start: {only_in: [now]}
    end: {only_in: [now]}
    quarters: {list: true}            # used for next and later
    owner: {required: false}
    team: {required: false}
    confidence: {enum: [high, medium, low]}
    depends_on: {list: true}
    effort: {required: false}
  variants:
    board: {group_by: goal, hide: [owner, effort, team], dependency: none, capacity: none}
    team: {hide: []}
    engineering: {show: [effort, tracker_links, drift], axis_unit: month}
    public: {group_by: theme, allow: [public_title, public_summary, announced_quarter], bars_only_if: announced, require_disclaimer: true}

texts.docs/research/templates/roadmap/release-:
layout:
  type: releases
  orientation: columns                # columns | rows
  release_fields:
    name: {required: true}
    target_date: {required: true, source: eng_tracker}
    status: {enum: [planning, in_progress, code_freeze, released, slipped]}
    health: {enum: [on_track, at_risk, off_track]}
    goal: {multiple: true}
  item_fields:
    title: {required: true}
    goal: {required: true, multiple: true, flag_if_missing: "serves no confirmed goal"}
    scope: {enum: [must, should, could]}
    readiness: {checklist: [spec, design, build, qa, docs, launch]}
    tracker_key: {required: false}    # epic or issue id
    estimate: {source: eng_tracker}
    planned: {source: roadmap}
    drift: {derived: true}            # estimate vs plan, and tracker scope vs PRD
    owner: {required: false}
    depends_on: {list: true}
  capacity:
    per_release: true
    source: eng_tracker
  markers:
    health: chip
    drift: badge                      # "+2w", "scope added", "not in PRD"
    dependency: list
  variants:
    board: {not_recommended: true, fallback_template: now-next-later}
    team: {hide: [tracker_key, estimate]}
    engineering: {hide: []}
    public: {relabel: changelog_preview, allow: [public_title, public_summary, release_name], dates_only_if: announced, require_disclaimer: true}
